/// butlerd JSON-RPC 2.0 error codes
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(transparent)]
pub struct Code(pub i64);

impl Code {
    /// An operation was cancelled gracefully
    pub const OPERATION_CANCELLED: Code = Code(499);
    /// An operation was aborted by the user
    pub const OPERATION_ABORTED: Code = Code(410);
    /// We tried to launch something, but the install folder just wasn't there
    pub const INSTALL_FOLDER_DISAPPEARED: Code = Code(404);
    /// We tried to install something, but could not find compatible uploads
    pub const NO_COMPATIBLE_UPLOADS: Code = Code(2001);
    /// This title is hosted on an incompatible third-party website
    pub const UNSUPPORTED_HOST: Code = Code(3001);
    /// Nothing that can be launched was found
    pub const NO_LAUNCH_CANDIDATES: Code = Code(5000);
    /// The launch target explicitly requested via LaunchParams.target
    /// did not match any launch target
    pub const LAUNCH_TARGET_NOT_FOUND: Code = Code(5001);
    /// The selected target's strategy is not in
    /// LaunchParams.allowedStrategies
    pub const LAUNCH_STRATEGY_NOT_ALLOWED: Code = Code(5002);
    /// Java Runtime Environment is required to launch this title.
    pub const JAVA_RUNTIME_NEEDED: Code = Code(6000);
    /// There is no Internet connection
    pub const NETWORK_DISCONNECTED: Code = Code(9000);
    /// API error
    pub const API_ERROR: Code = Code(12000);
    /// The database is busy
    pub const DATABASE_BUSY: Code = Code(16000);
    /// An install location could not be removed because it has active downloads
    pub const CANT_REMOVE_LOCATION_BECAUSE_OF_ACTIVE_DOWNLOADS: Code = Code(18000);
    /// The selected sandbox is not available on this system
    pub const SANDBOX_NOT_AVAILABLE: Code = Code(19000);
    /// The profile explicitly requested for an operation does not exist
    pub const NO_SUCH_PROFILE: Code = Code(20000);
}

