/// Every notification the daemon can send, decoded from its method name.
#[derive(Debug, Clone, PartialEq)]
pub enum AnyNotification {
    DownloadsDriveProgress(DownloadsDriveProgressNotification),
    DownloadsDriveStarted(DownloadsDriveStartedNotification),
    DownloadsDriveErrored(DownloadsDriveErroredNotification),
    DownloadsDriveFinished(DownloadsDriveFinishedNotification),
    DownloadsDriveDiscarded(DownloadsDriveDiscardedNotification),
    /// Sent during @@DownloadsDriveParams to inform on network
    /// status changes.
    DownloadsDriveNetworkStatus(DownloadsDriveNetworkStatusNotification),
    /// Sent any time butler needs to send a log message. The client should
    /// relay them in their own stdout / stderr, and collect them so they
    /// can be part of an issue report if something goes wrong.
    Log(LogNotification),
    /// The first notification sent when @@MetaFlowParams is called.
    MetaFlowEstablished(MetaFlowEstablishedNotification),
    /// Sent periodically during @@InstallPerformParams to inform on the current state of an install
    Progress(ProgressNotification),
    /// Each operation is made up of one or more tasks. This notification
    /// is sent during @@OperationStartParams whenever a specific task starts.
    TaskStarted(TaskStartedNotification),
    /// Sent during @@OperationStartParams whenever a task succeeds for an operation.
    TaskSucceeded(TaskSucceededNotification),
    /// Sent during @@InstallLocationsScanParams whenever
    /// a game is found.
    InstallLocationsScanYield(InstallLocationsScanYieldNotification),
    /// Sent during @@CheckUpdateParams, every time butler
    /// finds an update for a game. Can be safely ignored if displaying
    /// updates as they are found is not a requirement for the client.
    GameUpdateAvailable(GameUpdateAvailableNotification),
    /// Sent during @@LaunchParams, when the game is configured, prerequisites are installed
    /// sandbox is set up (if enabled), and the game is actually running.
    LaunchRunning(LaunchRunningNotification),
    /// Sent during @@LaunchParams, when the game has actually exited.
    LaunchExited(LaunchExitedNotification),
    /// Sent during @@LaunchParams, when some prerequisites are about to be installed.
    ///
    /// This is a good time to start showing a UI element with the state of prereq
    /// tasks.
    ///
    /// Updates are regularly provided via @@PrereqsTaskStateNotification.
    PrereqsStarted(PrereqsStartedNotification),
    /// Current status of a prerequisite task
    ///
    /// Sent during @@LaunchParams, after @@PrereqsStartedNotification, repeatedly
    /// until all prereq tasks are done.
    PrereqsTaskState(PrereqsTaskStateNotification),
    /// Sent during @@LaunchParams, when all prereqs have finished installing (successfully or not)
    ///
    /// After this is received, it's safe to close any UI element showing prereq task state.
    PrereqsEnded(PrereqsEndedNotification),
    /// Emitted once, as soon as the worker has obtained a build ID from the
    /// itch.io API (i.e. after CreateBuild succeeds, before any data flows).
    /// Lets the caller associate its in-flight push with the server-side
    /// build before the upload completes.
    PublishPushBuildAssigned(PublishPushBuildAssignedNotification),
    /// Emitted if Publish.Push errors out after a build was assigned and the
    /// worker successfully marked the build as failed on the server. Lets the
    /// caller update its local view of the build to "failed" without having
    /// to poll. If the push fails before a build was assigned, no notification
    /// is emitted (only the RPC error is surfaced).
    PublishPushBuildFailed(PublishPushBuildFailedNotification),
    /// Periodic progress update emitted while a Publish.Push is in flight.
    PublishPushProgress(PublishPushProgressNotification),
    /// A method these bindings do not know.
    Unknown {
        method: String,
        params: Value,
    },
}

impl AnyNotification {
    pub fn decode(method: &str, params: Value) -> Result<Self, serde_json::Error> {
        Ok(match method {
            "Downloads.Drive.Progress" => {
                Self::DownloadsDriveProgress(serde_json::from_value(params)?)
            }
            "Downloads.Drive.Started" => {
                Self::DownloadsDriveStarted(serde_json::from_value(params)?)
            }
            "Downloads.Drive.Errored" => {
                Self::DownloadsDriveErrored(serde_json::from_value(params)?)
            }
            "Downloads.Drive.Finished" => {
                Self::DownloadsDriveFinished(serde_json::from_value(params)?)
            }
            "Downloads.Drive.Discarded" => {
                Self::DownloadsDriveDiscarded(serde_json::from_value(params)?)
            }
            "Downloads.Drive.NetworkStatus" => {
                Self::DownloadsDriveNetworkStatus(serde_json::from_value(params)?)
            }
            "Log" => Self::Log(serde_json::from_value(params)?),
            "MetaFlowEstablished" => Self::MetaFlowEstablished(serde_json::from_value(params)?),
            "Progress" => Self::Progress(serde_json::from_value(params)?),
            "TaskStarted" => Self::TaskStarted(serde_json::from_value(params)?),
            "TaskSucceeded" => Self::TaskSucceeded(serde_json::from_value(params)?),
            "Install.Locations.Scan.Yield" => {
                Self::InstallLocationsScanYield(serde_json::from_value(params)?)
            }
            "GameUpdateAvailable" => Self::GameUpdateAvailable(serde_json::from_value(params)?),
            "LaunchRunning" => Self::LaunchRunning(serde_json::from_value(params)?),
            "LaunchExited" => Self::LaunchExited(serde_json::from_value(params)?),
            "PrereqsStarted" => Self::PrereqsStarted(serde_json::from_value(params)?),
            "PrereqsTaskState" => Self::PrereqsTaskState(serde_json::from_value(params)?),
            "PrereqsEnded" => Self::PrereqsEnded(serde_json::from_value(params)?),
            "Publish.Push.BuildAssigned" => {
                Self::PublishPushBuildAssigned(serde_json::from_value(params)?)
            }
            "Publish.Push.BuildFailed" => {
                Self::PublishPushBuildFailed(serde_json::from_value(params)?)
            }
            "Publish.Push.Progress" => Self::PublishPushProgress(serde_json::from_value(params)?),
            _ => Self::Unknown {
                method: method.to_string(),
                params,
            },
        })
    }
}

