/// Every request the daemon can make of the client mid-call, decoded
/// from its method name. The client must answer each with the matching
/// Result type.
#[derive(Debug, Clone, PartialEq)]
pub enum AnyServerRequest {
    /// Ask the user to solve a captcha challenge
    /// Sent during @@ProfileLoginWithPasswordParams if certain
    /// conditions are met.
    ProfileRequestCaptcha(ProfileRequestCaptchaParams),
    /// Ask the user to provide a TOTP token.
    /// Sent during @@ProfileLoginWithPasswordParams if the user has
    /// two-factor authentication enabled.
    ProfileRequestTOTP(ProfileRequestTOTPParams),
    /// Let the user pick which version to switch to.
    InstallVersionSwitchPick(InstallVersionSwitchPickParams),
    /// Asks the user to pick between multiple available uploads
    PickUpload(PickUploadParams),
    /// Sent at the end of @@InstallLocationsScanParams
    InstallLocationsScanConfirmImport(InstallLocationsScanConfirmImportParams),
    /// Sent during @@LaunchParams if the game/application comes with a service license
    /// agreement.
    AcceptLicense(AcceptLicenseParams),
    /// Sent during @@LaunchParams, ask the user to pick a manifest action to launch.
    ///
    /// See [itch app manifests](https://itch.io/docs/itch/integrating/manifest.html).
    PickManifestAction(PickManifestActionParams),
    /// Ask the client to perform a shell launch, ie. open an item
    /// with the operating system's default handler (File explorer).
    ///
    /// Sent during @@LaunchParams.
    ShellLaunch(ShellLaunchParams),
    /// Ask the client to perform an HTML launch, ie. open an HTML5
    /// game, ideally in an embedded browser.
    ///
    /// Sent during @@LaunchParams.
    HTMLLaunch(HTMLLaunchParams),
    /// Ask the client to perform an URL launch, ie. open an address
    /// with the system browser or appropriate.
    ///
    /// Sent during @@LaunchParams.
    URLLaunch(URLLaunchParams),
    /// Ask the user to allow sandbox setup. Will be followed by
    /// a UAC prompt (on Windows) or a pkexec dialog (on Linux) if
    /// the user allows.
    ///
    /// Sent during @@LaunchParams.
    AllowSandboxSetup(AllowSandboxSetupParams),
    /// Sent during @@LaunchParams, when one or more prerequisites have failed to install.
    /// The user may choose to proceed with the launch anyway.
    PrereqsFailed(PrereqsFailedParams),
    /// Test request: return a number, doubled. Implement that to
    /// use @@TestDoubleTwiceParams in your testing.
    TestDouble(TestDoubleParams),
    /// A method these bindings do not know.
    Unknown { method: String, params: Value },
}

impl AnyServerRequest {
    pub fn decode(method: &str, params: Value) -> Result<Self, serde_json::Error> {
        Ok(match method {
            "Profile.RequestCaptcha" => {
                Self::ProfileRequestCaptcha(serde_json::from_value(params)?)
            }
            "Profile.RequestTOTP" => Self::ProfileRequestTOTP(serde_json::from_value(params)?),
            "InstallVersionSwitchPick" => {
                Self::InstallVersionSwitchPick(serde_json::from_value(params)?)
            }
            "PickUpload" => Self::PickUpload(serde_json::from_value(params)?),
            "Install.Locations.Scan.ConfirmImport" => {
                Self::InstallLocationsScanConfirmImport(serde_json::from_value(params)?)
            }
            "AcceptLicense" => Self::AcceptLicense(serde_json::from_value(params)?),
            "PickManifestAction" => Self::PickManifestAction(serde_json::from_value(params)?),
            "ShellLaunch" => Self::ShellLaunch(serde_json::from_value(params)?),
            "HTMLLaunch" => Self::HTMLLaunch(serde_json::from_value(params)?),
            "URLLaunch" => Self::URLLaunch(serde_json::from_value(params)?),
            "AllowSandboxSetup" => Self::AllowSandboxSetup(serde_json::from_value(params)?),
            "PrereqsFailed" => Self::PrereqsFailed(serde_json::from_value(params)?),
            "Test.Double" => Self::TestDouble(serde_json::from_value(params)?),
            _ => Self::Unknown {
                method: method.to_string(),
                params,
            },
        })
    }
}

